<?php
namespace App\Http\Controllers; use App\Models\ContractTemplate; use App\Models\ContractTemplateVersion; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ContractTemplateVersionController extends Controller { public function index(ContractTemplate $template){return response()->json(['success'=>true,'data'=>$template->versions()->with('language')->orderByDesc('version_number')->get()]);} public function store(Request $r, ContractTemplate $template){$d=$r->validate(['language_id'=>['required','exists:languages,id'],'content'=>['required','string'],'status'=>['sometimes','in:draft,active,archived']]); return DB::transaction(function()use($d,$r,$template){$n=(int)$template->versions()->where('language_id',$d['language_id'])->lockForUpdate()->max('version_number')+1; $active=($d['status']??'draft')==='active'; if($active)$template->versions()->where('language_id',$d['language_id'])->update(['is_current'=>false]); $v=$template->versions()->create([...$d,'version_number'=>$n,'is_current'=>$active,'created_by'=>$r->user()?->id]); return response()->json(['success'=>true,'data'=>$v->load('language')],201);});} public function activate(ContractTemplate $template, ContractTemplateVersion $version){abort_unless($version->contract_template_id===$template->id,404); DB::transaction(function()use($template,$version){$template->versions()->where('language_id',$version->language_id)->update(['is_current'=>false]);$version->update(['status'=>'active','is_current'=>true]);}); return response()->json(['success'=>true,'data'=>$version->fresh('language')]);} }
